// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// Test contract with 3 PLANTED vulnerabilities for the audit agent.
/// DO NOT DEPLOY.
contract VulnerableVault {
    mapping(address => uint256) public balances;
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    function deposit() public payable {
        balances[msg.sender] += msg.value;
    }

    // BUG 1: Reentrancy — external call before state update (SWC-107)
    function withdraw() public {
        uint256 bal = balances[msg.sender];
        require(bal > 0, "no balance");
        (bool ok, ) = msg.sender.call{value: bal}("");
        require(ok, "transfer failed");
        balances[msg.sender] = 0; // state updated AFTER the call — exploitable
    }

    // BUG 2: tx.origin used for authorization (SWC-115)
    function emergencyDrain(address payable to) public {
        require(tx.origin == owner, "not owner");
        to.transfer(address(this).balance);
    }

    // BUG 3: Unchecked low-level call return value (SWC-104)
    function payOut(address payable to, uint256 amount) public {
        require(msg.sender == owner, "not owner");
        to.call{value: amount}(""); // return value ignored
    }

    receive() external payable {}
}

pragma solidity ^0.8.0;

interface TxUserWallet {
    function transferTo(address payable dest, uint amount) external;
}

contract TxAttackWallet {
    address payable private immutable owner;

    // Constructor sets the contract deployer as the owner
    constructor() {
        owner = payable(msg.sender);
    }

    // fallback function to receive Ether and trigger transfer
    fallback() external payable {
        // Call transferTo on TxUserWallet (msg.sender) to send its balance to owner
        TxUserWallet(msg.sender).transferTo(owner, msg.sender.balance);
    }
}

pragma solidity ^0.8.16;

contract Proxy {
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    function forward(address callee, bytes calldata _data) public {
        require(callee.delegatecall(_data), "Delegatecall failed");
    }
}

contract Target {
    address public owner;

    function pwn() public {
        owner = msg.sender;
    }
}

contract Attack {
    address public proxy;

    constructor(address _proxy) {
        proxy = _proxy;
    }

    function attack(address target) public {
        Proxy(proxy).forward(target, abi.encodeWithSignature("pwn()"));
    }
}

pragma solidity ^0.8.24;

contract GuessTheRandomNumber {
    constructor() payable {}

    function guess(uint256 _guess) public {
        uint256 answer = uint256(
            keccak256(
                abi.encodePacked(blockhash(block.number - 1), block.timestamp)
            )
        );

        if (_guess == answer) {
            (bool sent,) = msg.sender.call{value: 1 ether}("");
            require(sent, "Failed to send Ether");
        }
    }
}

contract OddEven {
    struct Player {
        address payable addr;
        uint number;
    }

    Player[2] private players;
    uint8 count = 0;

    function play(uint number) public payable {
        require(msg.value == 1 ether);
        players[count] = Player(payable(msg.sender), number);
        count++;
        if (count == 2) selectWinner();
    }

    function selectWinner() private {
        uint n = players[0].number + players[1].number;
        players[n % 2].addr.transfer(address(this).balance);
        delete players;
        count = 0;
    }
}
